extern "C" {
void kernel_trmm(
		 double alpha,
		 double A[ M + 0][M + 0],
		 double B[ M + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem1
#pragma HLS INTERFACE s_axilite port=alpha bundle=control
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int m = M;
    const int n = N;

    // Local on-chip buffers. M=60, N=80 -> small, fit in BRAM easily.
    static double A_loc[M][M];
    static double B_loc[M][N];
#pragma HLS ARRAY_PARTITION variable=A_loc cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=B_loc cyclic factor=8 dim=1

    // Burst-load A into local memory
LOAD_A_I:
    for (int i = 0; i < m; i++) {
    LOAD_A_J:
        for (int j = 0; j < m; j++) {
#pragma HLS PIPELINE II=1
            A_loc[i][j] = A[i][j];
        }
    }

    // Burst-load B into local memory
LOAD_B_I:
    for (int i = 0; i < m; i++) {
    LOAD_B_J:
        for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            B_loc[i][j] = B[i][j];
        }
    }

    // Compute on local memory
COMPUTE_I:
    for (int i = 0; i < m; i++) {
    COMPUTE_J:
        for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            double acc = B_loc[i][j];
        COMPUTE_K:
            for (int k = i + 1; k < m; k++) {
#pragma HLS UNROLL factor=8
                acc += A_loc[k][i] * B_loc[k][j];
            }
            B_loc[i][j] = alpha * acc;
        }
    }

    // Burst-store B back to DRAM
STORE_B_I:
    for (int i = 0; i < m; i++) {
    STORE_B_J:
        for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            B[i][j] = B_loc[i][j];
        }
    }
}
}
